previewCss:
.darma-loader-darma-b10-cross-pulse { --accent: var(--loader-color, #ef4444); --accent-2: var(--loader-secondary-color, #f87171); width: var(--loader-size, 72px); height: var(--loader-size, 72px); display: grid; place-items: center; }
.darma-loader-darma-b10-cross-pulse span { width: 26%; height: 80%; background: var(--accent); border-radius: calc(var(--loader-size, 72px) * .05); position: relative; box-shadow: 0 0 calc(var(--loader-size, 72px) * .16) color-mix(in srgb, var(--accent-2) 65%, transparent); animation: darma-loader-darma-b10-cross-pulse-cross calc(var(--loader-speed, 1s) * 1.6) ease-in-out infinite; }
.darma-loader-darma-b10-cross-pulse span::after { content: ''; position: absolute; top: 37%; left: -100%; width: 300%; height: 26%; background: inherit; border-radius: inherit; }
@keyframes darma-loader-darma-b10-cross-pulse-cross { 0%, 100% { transform: scale(.7) rotate(0deg); } 50% { transform: scale(1) rotate(90deg); } }

